import ast, hashlib, json, pathlib, sqlite3, subprocess
root = pathlib.Path('.')
def sha(b): return hashlib.sha256(b).hexdigest()
def snapshot():
    return {str(p): sha(p.read_bytes()) for p in sorted(root.rglob('*')) if p.is_file()}
def git_state():
    return {arg: subprocess.check_output(['git'] + arg.split()).decode() for arg in ['status --porcelain=v1 --untracked-files=all', 'diff --binary', 'diff --cached --binary', 'rev-parse HEAD']}
before, git_before = snapshot(), git_state()
source = pathlib.Path('readers.py').read_bytes()
reader_sql, provenance = {}, []
for node in ast.parse(source, filename='readers.py').body:
    if isinstance(node, ast.Assign):
        for target in node.targets:
            if isinstance(target, ast.Name) and target.id in ('OLD', 'NEW'):
                sql = ast.literal_eval(node.value)
                reader_sql[target.id] = sql
                provenance.append({'file': 'readers.py', 'constant': target.id, 'source_line': node.lineno, 'file_byte_sha256': sha(source), 'sql_utf8_byte_sha256': sha(sql.encode('utf-8')), 'exact_sql': sql})
assert list(reader_sql) == ['OLD', 'NEW']
conn = sqlite3.connect(':memory:')
phases = []
plan = [('001.sql', ['OLD']), ('002.sql', ['OLD']), ('003.sql', ['OLD', 'NEW']), (None, ['OLD']), ('004.sql', ['OLD'])]
def observe(sql):
    try:
        cur = conn.execute(sql)
        rows = [list(row) for row in cur.fetchall()]
        return {'columns': [d[0] for d in cur.description], 'rows': rows, 'error': None, 'complete': True, 'truncated': False}
    except sqlite3.Error as exc:
        return {'columns': None, 'rows': None, 'error': {'type': type(exc).__name__, 'message': str(exc), 'sqlite_errorcode': getattr(exc, 'sqlite_errorcode', None), 'sqlite_errorname': getattr(exc, 'sqlite_errorname', None)}, 'complete': True, 'truncated': False}
for step, (file, active) in enumerate(plan, 1):
    phase = {'step': step, 'name': file or 'drain NEW and restart OLD with no SQL', 'active_readers': active}
    if file:
        raw = pathlib.Path(file).read_bytes()
        phase['proposal'] = {'file': file, 'byte_sha256': sha(raw), 'exact_sql': raw.decode()}
        conn.executescript(raw.decode())
        conn.commit()
    else:
        phase['proposal'] = None
    phase['transaction_open_after_commit'] = conn.in_transaction
    phase['readers'] = {}
    for name, sql in reader_sql.items():
        expected = ([['A', 10], ['C', 0]] if step < 3 else [['A', 12], ['B', 4], ['C', 0]]) if name == 'OLD' else ([['A', 10], ['C', 0]] if step < 3 else [['A', 7], ['B', 3], ['C', 0]])
        result = observe(sql)
        result['active'] = name in active
        result['contract'] = {'columns': ['sku', 'units'], 'rows': expected}
        result['matches_contract'] = result['error'] is None and result['columns'] == ['sku', 'units'] and result['rows'] == expected
        result['active_failure'] = result['active'] and not result['matches_contract']
        phase['readers'][name] = result
    phase['committed_stock'] = observe('SELECT * FROM stock ORDER BY sku')
    phase['active_contracts_satisfied'] = all(not r['active_failure'] for r in phase['readers'].values())
    phases.append(phase)
expected_stock = {'columns': ['sku', 'quantity', 'reserved'], 'rows': [['A', 12, 5], ['B', 4, 1], ['C', 0, 0]]}
survival = { 'expected': expected_stock, 'matches_after_step_3': all(phases[2]['committed_stock'][k] == v for k, v in expected_stock.items()), 'matches_after_step_5': all(phases[4]['committed_stock'][k] == v for k, v in expected_stock.items())}
conn.close()
after, git_after = snapshot(), git_state()
record = {'format': 'friday-sql-observations-v1', 'engine': {'name': 'SQLite', 'version': sqlite3.sqlite_version, 'database': ':memory:'}, 'execution': 'Exact supplied SQL scripts in order, committed after each script; both literal readers separately executed at each phase, including no-SQL phase 4; all result rows fetched.', 'reader_provenance': provenance, 'phases': phases, 'committed_quantity_and_reservation_survival': survival, 'preservation': {'all_project_file_bytes_unchanged_including_git': before == after, 'git_state_unchanged': git_before == git_after, 'initial_git_status': git_before['status --porcelain=v1 --untracked-files=all'], 'scratch_created': False}, 'completion': {'complete': True, 'expected_phase_count': 5, 'recorded_phase_count': len(phases), 'expected_reader_observation_count': 10, 'recorded_reader_observation_count': sum(len(p['readers']) for p in phases), 'truncated': False, 'rows_omitted': 0}}
print(json.dumps(record, indent=2))
assert before == after and git_before == git_after
assert survival['matches_after_step_3'] and survival['matches_after_step_5']
